// ALL FIVE query approaches in one repository
package com.bank.query.repository;

import com.bank.query.model.Trade;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

public interface TradeRepository extends JpaRepository<Trade, String> {

    // ═══ 1. DERIVED METHODS — query from method name ═══
    List<Trade> findByStatus(String status);
    List<Trade> findByAccountIdAndStatus(String accountId, String status);
    List<Trade> findByAmountGreaterThan(BigDecimal amount);
    List<Trade> findBySymbolContainingIgnoreCase(String fragment);
    List<Trade> findByStatusOrderByAmountDesc(String status);
    long countByStatus(String status);
    boolean existsByAccountIdAndStatus(String accountId, String status);

    // ═══ 2. JPQL @Query — named parameters ═══
    @Query("SELECT t FROM Trade t WHERE t.amount BETWEEN :min AND :max AND t.status = :status")
    List<Trade> findByAmountRange(@Param("min") BigDecimal min,
                                  @Param("max") BigDecimal max,
                                  @Param("status") String status);

    // JPQL with aggregation:
    @Query("SELECT t.symbol, SUM(t.amount) FROM Trade t WHERE t.status = 'SETTLED' " +
           "GROUP BY t.symbol ORDER BY SUM(t.amount) DESC")
    List<Object[]> getTotalAmountPerSymbol();

    // ═══ 3. NATIVE SQL — database-specific ═══
    @Query(value = "SELECT * FROM trades WHERE settlement_date = :date AND amount > :min",
           nativeQuery = true)
    List<Trade> findLargeTradesForDateNative(@Param("date") LocalDate date,
                                            @Param("min") BigDecimal min);

    // Native with pagination (requires countQuery):
    @Query(value = "SELECT * FROM trades WHERE status = :status ORDER BY amount DESC",
           countQuery = "SELECT COUNT(*) FROM trades WHERE status = :status",
           nativeQuery = true)
    Page<Trade> findByStatusNativePaged(@Param("status") String status, Pageable pageable);

    // ═══ 4. @Modifying — bulk UPDATE ═══
    @Modifying(clearAutomatically = true)
    @Query("UPDATE Trade t SET t.status = :newStatus WHERE t.status = :oldStatus AND t.accountId = :accountId")
    int updateStatusForAccount(@Param("oldStatus") String oldStatus,
                               @Param("newStatus") String newStatus,
                               @Param("accountId") String accountId);

    // @Modifying — bulk DELETE:
    @Modifying
    @Query("DELETE FROM Trade t WHERE t.status = 'CANCELLED'")
    int deleteCancelled();
}
