package com.bank.query.service;

import com.bank.query.dto.QueryResult;
import com.bank.query.model.Trade;
import com.bank.query.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradeQueryService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public List<QueryResult> demonstrateAllApproaches() {
        List<QueryResult> results = new ArrayList<>();

        // 1. Derived
        List<Trade> settled = tradeRepo.findByStatusOrderByAmountDesc("SETTLED");
        results.add(new QueryResult("DERIVED: findByStatusOrderByAmountDesc",
            settled.size(), format(settled),
            "SELECT t FROM Trade t WHERE t.status = ?1 ORDER BY t.amount DESC"));

        // 2. JPQL @Query
        List<Trade> range = tradeRepo.findByAmountRange(
            new BigDecimal("100000"), new BigDecimal("300000"), "SETTLED");
        results.add(new QueryResult("JPQL @Query: findByAmountRange",
            range.size(), format(range),
            "SELECT t FROM Trade t WHERE t.amount BETWEEN :min AND :max AND t.status = :status"));

        // 3. Aggregation
        List<Object[]> totals = tradeRepo.getTotalAmountPerSymbol();
        List<String> aggDisplay = totals.stream()
            .map(row -> row[0] + ": Rs." + row[1]).toList();
        results.add(new QueryResult("JPQL AGGREGATION: getTotalAmountPerSymbol",
            totals.size(), aggDisplay,
            "SELECT t.symbol, SUM(t.amount) FROM Trade t GROUP BY t.symbol"));

        // 4. Native SQL
        List<Trade> nativeTrades = tradeRepo.findLargeTradesForDateNative(
            java.time.LocalDate.of(2024, 1, 15), new BigDecimal("200000"));
        results.add(new QueryResult("NATIVE SQL: findLargeTradesForDateNative",
            nativeTrades.size(), format(nativeTrades),
            "SELECT * FROM trades WHERE settlement_date = :date AND amount > :min"));

        return results;
    }

    @Transactional
    public int settleAllPending(String accountId) {
        // 5. @Modifying bulk update
        int updated = tradeRepo.updateStatusForAccount("PENDING", "SETTLED", accountId);
        log.info("@Modifying: {} trades updated PENDING→SETTLED for {}", updated, accountId);
        return updated;
    }

    private List<String> format(List<Trade> trades) {
        return trades.stream()
            .map(t -> t.getTradeId() + " " + t.getSymbol() + " Rs." + t.getAmount() + " [" + t.getStatus() + "]")
            .toList();
    }
}
