package com.bank.query.controller;

import com.bank.query.dto.QueryResult;
import com.bank.query.service.TradeQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/queries")
@RequiredArgsConstructor
public class TradeQueryController {

    private final TradeQueryService service;

    @GetMapping("/demo")
    public List<QueryResult> demo() { return service.demonstrateAllApproaches(); }

    @PostMapping("/settle/{accountId}")
    public Map<String, Object> settle(@PathVariable String accountId) {
        int count = service.settleAllPending(accountId);
        return Map.of("accountId", accountId, "updatedCount", count, "approach", "@Modifying bulk UPDATE");
    }
}
