package com.bank.query.repository;

import com.bank.query.model.Trade;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

@DataJpaTest
class CustomQueryTest {

    @Autowired TradeRepository tradeRepo;

    @Test
    void derivedMethodGeneratesCorrectQuery() {
        List<Trade> settled = tradeRepo.findByStatus("SETTLED");
        assertThat(settled).allMatch(t -> "SETTLED".equals(t.getStatus()));
    }

    @Test
    void jpqlQueryWithNamedParameters() {
        List<Trade> range = tradeRepo.findByAmountRange(
            new BigDecimal("100000"), new BigDecimal("300000"), "SETTLED");
        assertThat(range).allMatch(t ->
            t.getAmount().compareTo(new BigDecimal("100000")) >= 0 &&
            t.getAmount().compareTo(new BigDecimal("300000")) <= 0);
    }

    @Test
    void aggregationQuery() {
        List<Object[]> totals = tradeRepo.getTotalAmountPerSymbol();
        assertThat(totals).isNotEmpty();
        // Each row: [symbol, totalAmount]
        assertThat(totals.get(0)).hasSize(2);
    }

    @Test
    void countDerived() {
        long count = tradeRepo.countByStatus("SETTLED");
        assertThat(count).isGreaterThan(0);
    }

    @Test
    void existsDerived() {
        boolean exists = tradeRepo.existsByAccountIdAndStatus("SAV2001", "SETTLED");
        assertThat(exists).isTrue();
    }

    @Test
    void containsIgnoreCase() {
        List<Trade> found = tradeRepo.findBySymbolContainingIgnoreCase("reli");
        assertThat(found).extracting(Trade::getSymbol).allMatch(s -> s.toUpperCase().contains("RELI"));
    }
}
